package org.eva.vtiger.apiautomate;

public class Forloop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

	int[] marks=new int[3];
	marks[0]=80;
	marks[1]=99;
	marks[2]=98;
	System.out.println(marks[2 ]);
		  
	
	
	
	for(int i=1;i<=4;i++) {
		
		for(int j=i;j<=i;j++) {
			
			System.out.println("*");
		}}
	}
	
	

}
